"""Guide Registry - Tum sorun tipleri icin duzeltme rehberleri."""


class Guide:
    """Tek bir sorun tipi icin duzeltme rehberi."""
    def __init__(self, title, risk, what, why, steps, before, after, warning=None, tools=None):
        self.title = title
        self.risk = risk
        self.what = what
        self.why = why
        self.steps = steps
        self.before = before
        self.after = after
        self.warning = warning
        self.tools = tools or []

    def to_dict(self):
        return {
            "title": self.title, "risk": self.risk,
            "what": self.what, "why": self.why,
            "steps": self.steps,
            "before": self.before, "after": self.after,
            "warning": self.warning, "tools": self.tools,
        }


