class GuideRegistry:
    @staticmethod
    def get(subtype):
        g = GUIDES.get(subtype)
        return g.to_dict() if g else None

    @staticmethod
    def get_all():
        return {k: v.to_dict() for k, v in GUIDES.items()}

    @staticmethod
    def has(subtype):
        return subtype in GUIDES
